using System.ComponentModel.DataAnnotations;//Use this namespace to access the data annotation attributes like [Required], [StringLength], etc. that can be used to validate the properties of the DTO class.
namespace EmployeeManagementApi.DTOs
{
    //This class contains only properties that are to be filled by the user when creating a new employee record. It does not include properties like EmployeeId and CreatedDate that are generated by the system.
    public class EmployeeRequestDto
    {
        [Required(ErrorMessage = "Employee name is required.")]
        [StringLength(100, MinimumLength =3, ErrorMessage = "Employee name cannot exceed 100 characters.")]
        public string EmployeeName { get; set; } = string.Empty;

        [Required(ErrorMessage = "Employee Email is required.")]
        [EmailAddress(ErrorMessage = "Invalid email format.")]
        public string Email { get; set; } = string.Empty;

        [Required(ErrorMessage = "Employee Department is required.")]
        [StringLength(50, MinimumLength = 3, ErrorMessage = "Department name must be between 3 and 50 characters.")]
        public string Department { get; set; } = string.Empty;

        [Required(ErrorMessage = "Employee City is required.")]
        [StringLength(50, MinimumLength = 3, ErrorMessage = "City name must be between 3 and 50 characters.")]
        public string City { get; set; } = string.Empty;
    }

    //Todo: Create a ResponseDTO class that will be used to send the employee data back to the client. This class should include all properties of the Employee model, including EmployeeId and CreatedDate.
    public class EmployeeResponseDto
    {
        public int EmployeeId { get; set; }

        public string EmployeeName { get; set; } = string.Empty;

        public string Email { get; set; } = string.Empty;

        public string Department { get; set; } = string.Empty;

        public string City { get; set; } = string.Empty;

        public DateTime CreatedDate { get; set; }
    }

    /// <summary>
    /// Represents the DTO for updating City of an Employee. This DTO is used to encapsulate the data required for updating the City property of an existing Employee record in the database.
    /// </summary>
    public class UpdateCityRequestDto
    {
        [Required(ErrorMessage = "Employee City is required.")]
        [StringLength(50, MinimumLength = 3, ErrorMessage = "City name must be between 3 and 50 characters.")]
        public string City { get; set; } = string.Empty;


    }
}

